// Convertir Base64 a Binario de forma robusta
const body = $input.first().json.body || $input.first().json;
const imageData = body.image || '';

if (!imageData) {
  throw new Error('No se recibió ninguna imagen en el campo "image"');
}

let base64Image = '';
if (imageData.includes(',')) {
  base64Image = imageData.split(',')[1];
} else {
  base64Image = imageData;
}

const mimeType = imageData.match(/data:(.*?);/)?.[1] || 'image/jpeg';

return [{
  json: {
    ...body,
    imageBase64: base64Image,
    imageMimeType: mimeType
  },
  binary: {
    data: {
      data: base64Image,
      mimeType: 'image/jpeg',
      fileName: 'producto.jpg'
    }
  }
}];

// Construir request body para Anthropic Vision API
const prevData = $input.first().json;

const requestBody = {
  model: 'claude-sonnet-4-5-20250929',
  max_tokens: 1500,
  messages: [{
    role: 'user',
    content: [
      {
        type: 'image',
        source: {
          type: 'base64',
          media_type: prevData.imageMimeType || 'image/jpeg',
          data: prevData.imageBase64
        }
      },
      {
        type: 'text',
        text: 'Analiza el producto de esta imagen y genera un guion publicitario emocionante de 40 palabras para un avatar de IA. Responde únicamente con el guion, sin introducciones.'
      }
    ]
  }]
};

return [{ json: { requestBody } }];

// Preparar el paquete para HeyGen V2 usando la respuesta de Claude
const apiResponse = $input.first().json;
const script = apiResponse.content?.[0]?.text || 'Descubre este increíble producto diseñado para ti.';

return [{
  json: {
    video_inputs: [{
      character: {
        type: 'avatar',
        avatar_id: 'Abigail_standing_office_front',
        avatar_style: 'normal'
      },
      voice: {
        type: 'text',
        input_text: script,
        voice_id: '2d5bcf07da7b4e7da3907f1cb96da03a'
      }
    }],
    dimension: { width: 1080, height: 1920 }
  }
}];

// Bucle robusto de espera (Polling interno)
const responseData = $input.first().json;
const videoId = responseData.data?.video_id;

if (!videoId) {
  throw new Error('HeyGen no retornó video_id. Respuesta: ' + JSON.stringify(responseData).substring(0, 500));
}

const apiKey = $env.HEYGEN_API_KEY;
if (!apiKey) {
  throw new Error('Variable de entorno HEYGEN_API_KEY no configurada.');
}

let videoUrl = null;

for (let i = 0; i < 30; i++) {
  const response = await fetch(`https://api.heygen.com/v1/video_status.get?video_id=${videoId}`, {
    headers: { 'X-Api-Key': apiKey }
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(`HeyGen polling HTTP ${response.status}: ${errorText.substring(0, 300)}`);
  }

  const result = await response.json();

  if (result.data?.status === 'completed') {
    videoUrl = result.data.video_url;
    break;
  }

  if (result.data?.status === 'failed') {
    throw new Error('HeyGen falló: ' + (result.data.error || JSON.stringify(result)));
  }

  await new Promise(r => setTimeout(r, 5000));
}

if (!videoUrl) throw new Error('Tiempo de espera agotado (150s)');

return [{ json: { videoUrl } }];
